import streamlit as st
import pickle
import re
import nltk
from nltk.corpus import stopwords
from nltk.stem import PorterStemmer

# Set page configuration to wide layout for the columns
st.set_page_config(page_title="CineReview", layout="wide")

# --- Functions and Data Loading ---
def local_css(file_name):
    with open(file_name) as f:
        st.markdown(f"<style>{f.read()}</style>", unsafe_allow_html=True)

local_css("style.css")
nltk.download('stopwords')

try:
    with open('model.pkl', 'rb') as f:
        model = pickle.load(f)
    with open('vectorizer.pkl', 'rb') as f:
        vectorizer = pickle.load(f)
except FileNotFoundError:
    st.error("Model or vectorizer not found. Please ensure 'model.pkl' and 'vectorizer.pkl' are present.")
    st.stop()

stop_words = set(stopwords.words('english'))
stemmer = PorterStemmer()

def clean_text(text):
    text = re.sub(r'<.*?>', '', text)
    text = re.sub(r'[^a-zA-Z]', ' ', text)
    text = text.lower()
    words = text.split()
    words = [stemmer.stem(word) for word in words if word not in stop_words]
    return ' '.join(words)

# --- PASTE YOUR BASE64 CODES HERE ---
# Replace the placeholder text with the actual base64 code for each image.
image1_base64 = "data:image/jpeg;base64,"
image2_base64 = "data:image/jpeg;base64,"
image3_base64 = "data:image/jpeg;base64,"
image4_base64 = "data:image/jpeg;base64,"
image5_base64 = "data:image/jpeg;base64,"


base64_images = [image1_base64, image2_base64, image3_base64, image4_base64, image5_base64]

# --- UI Layout and Elements ---
left_col, main_col, right_col = st.columns([1, 1.5, 1]) # Center column is wider

# Left Scrolling Column (Bottom to Top)
with left_col:
    image_html_up = "".join([f'<img src="{b64_string}" alt="scrolling image">' for b64_string in base64_images * 2])
    st.markdown(
        f'<div class="scrolling-column"><div class="image-track-up">{image_html_up}</div></div>',
        unsafe_allow_html=True
    )

# Main Center Column (Your App)
with main_col:
    # Use columns to center the logo
    _, logo_col, _ = st.columns([1, 1.5, 1])
    with logo_col:
        try:
            st.image("static/logo.png", width=200)
        except:
            st.write("") # Fails gracefully if no logo is found

    st.title("CineReview")
    st.subheader("Unveiling the sentiment behind the script.")

    user_input = st.text_area(
        label=" ",
        placeholder="Enter a movie review to analyze...",
        key="review_text",
        height=250,
        label_visibility="collapsed"
    )

    if st.button("Analyze Sentiment"):
        if user_input:
            cleaned_input = clean_text(user_input)
            input_vector = vectorizer.transform([cleaned_input])
            prediction = model.predict(input_vector)[0]
            if prediction == 1:
                st.success("This appears to be a Positive review! ✨")
            else:
                st.error("This appears to be a Negative review. 😕")
        else:
            st.warning("Please enter a review to analyze!")

# Right Scrolling Column (Top to Bottom)
with right_col:
    reversed_base64_images = base64_images[::-1]
    image_html_down = "".join([f'<img src="{b64_string}" alt="scrolling image">' for b64_string in reversed_base64_images * 2])
    st.markdown(
        f'<div class="scrolling-column"><div class="image-track-down">{image_html_down}</div></div>',
        unsafe_allow_html=True
    )